void unit_test_newNode_basic_allocation(void) {
    // Setup: choose a test key value
    int test_key = 123;

    // Test: call newNode with the test key
    struct node* result = newNode(test_key);

    // Assertions: verify the node is allocated and initialized correctly
    assert(result != NULL);
    assert(result->key == test_key);
    assert(result->left == NULL);
    assert(result->right == NULL);

    // Cleanup: free the allocated node
    free(result);
}
